import re
from pathlib import Path
from collections import defaultdict

store_entities = ['Store', 'Memo']

for entity in store_entities:
    ref_packages = set()

    for go_file in Path('/bench/home/work').rglob('*.go'):
        # Skip store and proto files
        if 'store' in go_file.parts or 'proto' in go_file.parts:
            continue
        if not go_file.is_file():
            continue

        try:
            content = go_file.read_text(encoding='utf-8', errors='ignore')
        except:
            continue

        # Get package path
        package_path = '/'.join(go_file.parts[go_file.parts.index('work')+1:-1])
        if not package_path:
            continue

        # Look for the entity type name
        pattern = r'\b' + entity + r'\b'
        if re.search(pattern, content):
            ref_packages.add(package_path)

    print(f"{entity} ({len(ref_packages)} packages):")
    for pkg in sorted(ref_packages):
        print(f"  - {pkg}")
    print()

EOF
